// Pick the single newest file in the folder by modifiedTime, and
// decide whether it's one we've already processed. Uses n8n's workflow
// static data as the idempotency store — brief §Non-negotiables:
// "Re-running the same file must overwrite the same rows, never append
// duplicates."
const items = $input.all();

if (!items.length) {
  throw new Error('No files found in the Stock Valuation Drive folder. Nothing to process.');
}

const withTime = items
  .map((it) => it.json)
  .filter((f) => f && f.id && f.modifiedTime)
  .sort((a, b) => new Date(b.modifiedTime) - new Date(a.modifiedTime));

if (!withTime.length) {
  throw new Error('Files were found but none carried an id + modifiedTime — check the Drive node output shape.');
}

const newest = withTime[0];
const store = $getWorkflowStaticData('node');
const lastId = store.lastFileId || null;
const lastModified = store.lastModifiedTime || null;

const isNew = newest.id !== lastId || newest.modifiedTime !== lastModified;

return [
  {
    json: {
      fileId: newest.id,
      fileName: newest.name,
      modifiedTime: newest.modifiedTime,
      isNew,
      lastFileIdSeen: lastId,
    },
  },
];

// Validate before anything is written anywhere — brief §Stage 4:
// "Any failure returns a rejection reason and the run stops. Never
// process a malformed file partially."
const rows = $input.all().map((it) => it.json);

if (rows.length < 50) {
  throw new Error(`Stock Valuation file has only ${rows.length} data rows — expected several hundred. Refusing to process what looks like a partial or wrong file.`);
}

const REQUIRED_HEADERS = ['Item Code', 'Item Name', 'Closing Qty Base UOM', 'Closing Cost Amount'];
const sampleKeys = Object.keys(rows[0] || {}).map((k) => String(k).trim());
const missing = REQUIRED_HEADERS.filter((h) => !sampleKeys.includes(h));

if (missing.length) {
  throw new Error(`Stock Valuation file is missing expected column(s): ${missing.join(', ')}. Header signature has changed — stopping rather than writing a mismatched file.`);
}

return $input.all();

const rows = $input.all();
const cleanedRows = [];

for (const item of rows) {
  const row = item.json || {};

  const hasAnyValue = Object.values(row).some(value => {
    if (value === null || value === undefined) return false;
    return String(value).trim() !== '';
  });

  if (!hasAnyValue) continue;

  const cleanedRow = {};

  for (const [key, value] of Object.entries(row)) {
    const cleanKey = String(key || '')
      .replace(/\r/g, ' ')
      .replace(/\n/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    if (!cleanKey) continue;
    cleanedRow[cleanKey] = value;
  }

  cleanedRows.push(cleanedRow);
}

if (cleanedRows.length === 0) {
  throw new Error('No usable data rows were extracted from the Stock Valuation file.');
}

return [
  {
    json: {
      rowCount: cleanedRows.length,
      rows: cleanedRows
    }
  }
];

const source = $('Bundle Rows (collapse to 1 item)').first().json;
const rows = source.rows || [];

if (!Array.isArray(rows) || rows.length === 0) {
  throw new Error('No bundled rows available for append.');
}

return rows.map(row => ({ json: row }));

// Commit the idempotency marker only now that the whole pipeline has
// succeeded — clear, write and the Apps Script sync all completed without
// throwing. Brief §Non-negotiables: "Idempotent runs... re-running the
// same file must overwrite the same rows, never append duplicates."
const picked = $('Pick Newest & Check Idempotency').first().json;
const store = $getWorkflowStaticData('node');
store.lastFileId = picked.fileId;
store.lastModifiedTime = picked.modifiedTime;
store.lastRunAt = new Date().toISOString();

return [{ json: { committed: true, fileId: picked.fileId, fileName: picked.fileName } }];
